import { useMemo, type ReactNode } from 'react';

import { CedrosLoginAdminRuntimeContext, type CedrosLoginAdminRuntimeValue } from './CedrosLoginAdminRuntimeContext';
import type { AuthUser } from '../types';
import type { AdminSectionProps } from './types';

interface CedrosLoginPluginData {
  user?: {
    id: string;
    email?: string;
    name?: string;
    picture?: string;
  } | null;
}

function normalizeAdminUser(user: CedrosLoginPluginData['user']): AuthUser | null {
  return user
    ? {
        authMethods: [],
        emailVerified: false,
        createdAt: '',
        updatedAt: '',
        ...user,
      }
    : null;
}

function buildRuntimeValue(pluginContext: AdminSectionProps['pluginContext']): CedrosLoginAdminRuntimeValue {
  const user = normalizeAdminUser((pluginContext.pluginData as CedrosLoginPluginData | undefined)?.user);

  return {
    config: {
      serverUrl: pluginContext.serverUrl,
    },
    user,
    authState: user ? 'authenticated' : 'unauthenticated',
    getAccessToken: pluginContext.getAccessToken,
  };
}

export function CedrosLoginAdminRuntimeProvider({
  pluginContext,
  children,
}: {
  pluginContext: AdminSectionProps['pluginContext'];
  children: ReactNode;
}) {
  const value = useMemo(() => buildRuntimeValue(pluginContext), [pluginContext]);

  return (
    <CedrosLoginAdminRuntimeContext.Provider value={value}>{children}</CedrosLoginAdminRuntimeContext.Provider>
  );
}
