/**
 * Cedros Login Admin Plugin
 *
 * Exports the cedrosLoginPlugin for use with AdminShell.
 * Provides user management, deposits, withdrawals, and configuration sections.
 */

import { lazy, type ComponentType, type ReactNode } from 'react';
import { HOST_SERVICE_IDS, getHostService } from '@cedros/admin-react';
import type {
  AdminPlugin,
  HostContext,
  PluginContext,
  AdminSectionConfig,
  AdminSectionProps,
} from './types';
import { AdminPluginIcons } from './icons';
import { CedrosLoginAdminRuntimeProvider } from './CedrosLoginAdminRuntimeProvider';

// ============================================================================
// Lazy-loaded Section Components
// ============================================================================

type AdminSectionComponent = (props: AdminSectionProps) => ReactNode;

const wrapSection = (importFn: () => Promise<{ default: ComponentType<AdminSectionProps> }>): AdminSectionComponent =>
  lazy(async () => {
    const module = await importFn();
    const OriginalComponent = module.default;

    return {
      default: function WrappedCedrosLoginAdminSection(props: AdminSectionProps) {
        return (
          <CedrosLoginAdminRuntimeProvider pluginContext={props.pluginContext}>
            <OriginalComponent {...props} />
          </CedrosLoginAdminRuntimeProvider>
        );
      },
    };
  });

const UsersSection = wrapSection(() => import('./sections/UsersSection'));
const TeamSection = wrapSection(() => import('./sections/TeamSection'));
const DepositsSection = wrapSection(() => import('./sections/DepositsSection'));
const WithdrawalsSection = wrapSection(() => import('./sections/WithdrawalsSection'));
const AuthenticationSettings = wrapSection(() => import('./sections/AuthenticationSettings'));
const EmbeddedWalletSettings = wrapSection(() => import('./sections/EmbeddedWalletSettings'));
const EmailSettings = wrapSection(() => import('./sections/EmailSettings'));
const WebhookSettings = wrapSection(() => import('./sections/WebhookSettings'));
const CreditSystemSettings = wrapSection(() => import('./sections/CreditSystemSettings'));
const ServerSettings = wrapSection(() => import('./sections/ServerSettings'));

// ============================================================================
// Permission Mapping
// ============================================================================

type LoginPermission =
  | 'login:users:read'
  | 'login:users:write'
  | 'login:members:read'
  | 'login:members:write'
  | 'login:invites:read'
  | 'login:invites:write'
  | 'login:deposits:read'
  | 'login:deposits:write'
  | 'login:settings:read'
  | 'login:settings:write';

type CedrosLoginHostService = NonNullable<HostContext['cedrosLogin']>;
type OrgHostService = NonNullable<HostContext['org']>;

/**
 * Maps plugin permissions to org-level permissions/roles.
 */
const PERMISSION_MAP: Record<LoginPermission, string[]> = {
  'login:users:read': ['admin', 'owner'],
  'login:users:write': ['admin', 'owner'],
  'login:members:read': ['member:read', 'admin', 'owner'],
  'login:members:write': ['member:remove', 'member:role_change'],
  'login:invites:read': ['invite:read', 'admin', 'owner'],
  'login:invites:write': ['invite:create', 'invite:cancel'],
  'login:deposits:read': ['admin', 'owner'],
  'login:deposits:write': ['admin', 'owner'],
  'login:settings:read': ['admin', 'owner'],
  'login:settings:write': ['admin', 'owner'],
};

